function reverseAdjectiveOrder(sentence) {
  // Split the sentence into words
  const words = sentence.split(' ');

  // Initialize empty arrays for adjectives and other words
  const adjectives = [];
  const otherWords = [];

  // Iterate through each word and determine if it's an adjective or not
  for (const word of words) {
    const partOfSpeech = getPartOfSpeech(word);
    if (partOfSpeech === 'adjective') {
      adjectives.unshift(word);
    } else {
      otherWords.push(word);
    }
  }

  // Join the arrays back into a sentence with the reversed order of adjectives
  const reversedAdjectives = adjectives.join(' ') + ' ';
  const result = reversedAdjectives + otherWords.join(' ');

  return result;
}
