```java
public static void playAudio(String fileName, boolean loop) throws UnsupportedAudioFileException, IOException, LineUnavailableException {
  AudioInputStream stream = getAudioStream(fileName);
  Clip clip = AudioSystem.getClip();
  clip.open(stream);

  if (loop) {
    clip.loop(Clip.LOOP_CONTINUOUSLY);
  } else {
    clip.start();
    clip.runAsync(() -> {
      try {
        Thread.sleep((int) Math.toLong(clip.getMicrosecondLength()));
      } catch (InterruptedException e) {
        e.printStackTrace();
      }
      clip.stop();
    });
  }
}
```

