using namespace std;

int fibonacci(int n, int a = 0, int b = 1) {
    if (n <= 0) throw invalid_argument("Invalid input. Please enter a positive integer for the number of sequence elements.");
    if (n == 1) return a;
    else return fibonacci(n - 1, b, a + b);
}

