 I'd be happy to help you create a generic REST service wrapper class in C# with auth token handling. Here's an example using the `HttpClient` class and the `Newtonsoft.Json` library:

```csharp
using System;
using System.Net.Http;
using System.Text;
using Newtonsoft.Json;

public class RestServiceWrapper<T> where T : new()
{
    private readonly string baseUrl;
    private readonly HttpClient httpClient;
    private string accessToken;

    public RestServiceWrapper(string baseUrl)
    {
        this.baseUrl = baseUrl;
        this.httpClient = new HttpClient();
    }

    public void SetAccessToken(string token)
    {
        if (string.IsNullOrEmpty(token)) throw new ArgumentNullException(nameof(token));
        this.accessToken = token;
        this.httpClient.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", this.accessToken);
    }

    public async Task<T> GetAsync(string endpoint)
    {
        using (var response = await this.httpClient.GetAsync($"{this.baseUrl}/{endpoint}"))
        {
            if (!response.IsSuccessStatusCode) throw new Exception($"Error getting data from server: Status Code={response.StatusCode}");
            var contentString = await response.Content.ReadAsStringAsync();
            return JsonConvert.DeserializeObject<T>(contentString);
        }
    }

    public async Task<T> PostAsync(string endpoint, object data)
    {
        using (var request = new StringContent(JsonConvert.SerializeObject(data), Encoding.UTF8, "application/json"))
        {
            using (var response = await this.httpClient.PostAsync($"{this.baseUrl}/{endpoint}", request))
            {
                if (!response.IsSuccessStatusCode) throw new Exception($"Error posting data to server: Status Code={response.StatusCode}");
                var contentString = await response.Content.ReadAsStringAsync();
                return JsonConvert.DeserializeObject<T>(contentString);
            }
        }
    }
}
