function determineProtocol(inputData) {
  let protocol;
  if (inputData.protocol) { // In case inputData already has a protocol field
    protocol = inputData.protocol;
  } else {
    if (inputData.sourceIP && inputData.destinationIP) { // For IP-based protocol determination
      if (inputData.sourceIP.match(/^[0-9a-f:]{15}([0-9a-f]{1,4})$/) && // IPv6 validation
          inputData.destinationIP.match(/^[0-9a-f:]{15}([0-9a-f]{1,4})$/)) { // IPv6 validation
        if (inputData.port === 80) { // HTTP uses port 80 by default for IPv6
          protocol = 'HTTP';
        } else if (typeof inputData.payload === 'string') { // Payload indicates application layer communication
          if (inputData.payload.length > 0) { // Empty payload doesn't provide enough information
            protocol = 'UDP' || /\?.+/.test(new URLSearchParams(inputData.payload).toString()); // Check for query string in payload for HTTP
          }
        } else {
          protocol = 'IPv6';
        }
      } else { // IPv4 or incorrect IPv6 format
        console.error('Invalid IP addresses.');
        return;
      }
    } else if (inputData.port) { // For port-based protocol determination
      if (inputData.port === 80) { // Default HTTP port
        protocol = 'HTTP';
      } else if (inputData.payload && typeof inputData.payload === 'string') { // Application layer communication with custom port
        protocol = 'UDP';
      }
    }
  }
  return protocol;
}
