    const authHeader = req.headers['authorization'];
    const bearer = authHeader && authHeader.split(' ')[0] === 'Bearer' ? authHeader.split(' ')[1] : null;
    const decoded = bearer && JSON.parse(Buffer.from(bearer, 'base64url').toString('ascii')) || null;

    if (!decoded || !appRoles.includes(decoded.role)) {
      return res.status(401).send({ message: 'Unauthorized' });
    }

    req.user = decoded;
    next();
  });

  app.use('/api/users', UserService);
  app.use('/api/permissions', new PermissionGuard().bind(new UserService()));

