import numpy as np

def sigmoid(x):
    return 1 / (1 + np.exp(-x))

def sigmoid_linear(x, inflection_point=0.5, power=3):
    """
    Maps input x from 0..1 to 0..1 with a smooth start, linear midrange, and smooth end.

    :param x: float or numpy array in the range [0, 1]
    :param inflection_point: The value at which the linear range occurs
    :param power: The power of the sigmoid function for the smooth start and end
    :return: Output in the range [0, 1]
    """

    # Calculate the smoothed sigmoid function
    smoothed_sigmoid = lambda x: sigmoid(power * x)

    # Determine if we're in the smooth start, linear midrange, or smooth end region
    if x < inflection_point - 0.05:
        # In smooth start region, map x to [0, inflection_point-0.05] using sigmoid function
        return smoothed_sigmoid(x / (inflection_point - 0.05))

    elif x > inflection_point + 0.05:
        # In smooth end region, map x to [inflection_point+0.05, 1] using inverse sigmoid function
        return 1 - smoothed_sigmoid(1 - x / (1 - inflection_point - 0.05))

    else:
        # In linear midrange region, map x linearly
        return x

# Testing
