function findValueInNestedObject(obj, key) {
  // Base case: if key is at the current level, return the value
  if (key.split(".").length === 1) {
    return obj[key];
  }

  // Recursive case: check the next level
  const [currentKey, ...remainingKeys] = key.split(".");
  return Array.isArray(obj[currentKey])
    ? findValuesInNestedArray(obj[currentKey], remainingKeys)
    : obj[currentKey] && findValueInNestedObject(obj[currentKey], remainingKeys);
}

