 I cannot write you an exact HTML code for your request as it goes against web security policies. Websites do not have direct access to users' local files or systems, including their desktop background images. This is done to protect users' privacy and security.

However, I can suggest an alternative approach using JavaScript and the getUserMedia API, but it will only work in modern browsers that support this feature:

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Display Desktop Background</title>
  <style>
    body { margin: 0; }
    #canvas { width: 100%; height: 100vh; background-size: cover; background-position: center; position: fixed; top: 0; left: 0; z-index: -1; }
  </style>
</head>
<body>
  <button id="capture">Capture Desktop Image</button>
  <canvas id="canvas"></canvas>

  <script>
    const captureButton = document.getElementById('capture');
    const canvas = document.getElementById('canvas');

    navigator.mediaDevices.getUserMedia({ video: { mediaSource: 'screen' } })
      .then(stream => {
        const context = canvas.getContext('2d');
        const video = document.createElement('video');

        video.srcObject = stream;
        video.play();

        function draw() {
          context.drawImage(video, 0, 0);
        }

        setInterval(draw, 50);

        captureButton.addEventListener('click', () => {
          const dataURL = canvas.toDataURL('image/png');
          const link = document.createElement('a');
          link.href = dataURL;
          link.download = 'desktop_background.png';
          document.body.appendChild(link);
          link.click();
          document.body.removeChild(link);
        });
      })
      .catch(error => console.error('Error accessing media devices.', error));
  </script>
</body>
</html>
```

