<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Upload Desktop Background Image</title>
    <style>
        #image-preview {
            width: 300px;
            height: 200px;
            object-fit: cover;
            margin: auto;
            display: block;
        }
    </style>
</head>
<body>
    <button id="upload-btn" onclick="selectFile()">Click here to upload your desktop background image</button>
    <input type="file" id="fileInput" style="display: none;" accept="image/*" onchange="handleFiles(event)">
    <img id="image-preview" src="" alt="Desktop Background Preview">

    <script src="app.js"></script>
</body>
</html>
```

2. Create an `app.js` file with the following content:

```javascript
document.addEventListener("DOMContentLoaded", function () {
    document.getElementById('upload-btn').addEventListener('click', selectFile);

    function selectFile() {
        document.getElementById('fileInput').click();
    }

    function handleFiles(event) {
        const files = event.target.files;
        if (files && files[0]) {
            const reader = new FileReader();

            reader.onload = function (e) {
                document.getElementById('image-preview').src = e.target.result;
            };

            reader.readAsDataURL(files[0]);
        }
    }
});

