    % Calculate fitness for each individual based on its trait
    fitness_p1 = 1 .+ (p1 .> 0.5) .* selection_coeff; % Fitness is 1 + selection coefficient if trait is advantageous
    fitness_p2 = 1 .- (p2 .> 0.5) .* selection_coeff; % Fitness is 1 - selection coefficient if trait is not advantageous

