#include <stdio.h>
#include <stdlib.h> // For malloc() and realloc()
#include <string.h> // For strcat() and strlen()

size_t argv_to_single_string(int argc, char **argv, char **out_str) {
    size_t total_length = 0;
    for (int i = 0; i < argc; ++i) {
        total_length += strlen(argv[i]) + 1; // +1 for space between arguments
    }
    total_length += argc - 1; // +1 for initial space and +1 for final null terminator

    *out_str = malloc(total_length * sizeof(char));
    if (*out_str == NULL) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0, index = 0; i < argc; ++i) {
        size_t arg_length = strlen(argv[i]);
        strcat(*out_str, argv[i]);
        strcat(*out_str, (i < argc - 1) ? " " : "");
        *out_str += arg_length + 1;
        index += arg_length + 1;
    }

    return total_length;
}

int main(int argc, char **argv) {
    char buffer[4096];
    size_t length = argv_to_single_string(argc, argv, &buffer);
    printf("Combined string: %.*s\n", (int)length, buffer);
    free(buffer);
    return EXIT_SUCCESS;
}
```

