// Define the specific product and time frame for identifying loyal customers
$product = 'coffee'; // replace with the specific product name
$start_date = date('Y-m-d', strtotime('last Monday')); // last Monday of the current week
$end_date = date('Y-m-d'); // today's date

// Query the transaction database to find customers who have purchased the specified product at least 3 times within the given time frame
$sql = "SELECT customers.name, COUNT(*) as purchase_count FROM transactions
        INNER JOIN products ON transactions.product_id = products.id
        INNER JOIN customers ON transactions.customer_id = customers.id
        WHERE products.name = '$product' AND transactions.transaction_date BETWEEN '$start_date' AND '$end_date'
        GROUP BY transactions.customer_id
        HAVING purchase_count >= 3";

$result = $conn->query($sql);

if ($result->num_rows > 0) {
    echo "Loyal Customers:\n";
    while($row = $result->fetch_assoc()) {
        echo "- " . $row["name"] . " (" . $row["purchase_count"] . " purchases)\n";
    }
} else {
    echo "No loyal customers found.";
}

// Close connection
$conn->close();
?>
```

