 To create a decorator for Nest.js middleware that checks the `NODE_ENV` variable and returns `next()` if it's set to `true`, otherwise returns `false`, you can follow these steps:

First, let's define a new decorator called `CheckNodeEnv`. This decorator will accept an optional argument named `allowedEnv` which specifies the list of allowed `NODE_ENV` values. By default, only the value `"production"` is allowed.

```typescript
import { createParamDecorator, ExecutionContext } from '@nestjs/common';

export const CheckNodeEnv = (allowedEnv: string[] = ['production']) => {
  return createParamDecorator(
    (data: unknown, ctx: ExecutionContext) => {
      const req = ctx.switchToHttp().getRequest();
      const nodeEnv = process.env.NODE_ENV;

      if (!allowedEnv.includes(nodeEnv)) {
        throw new Error(`Invalid NODE_ENV: ${nodeEnv}`);
      }

      return { nodeEnv };
    },
  );
};
```

Now, let's create the middleware function that uses the `CheckNodeEnv` decorator. The middleware function checks the decorated request object and calls `next()` if `NODE_ENV` is `true`, or returns `false` otherwise.

```typescript
import { Injectable, NestMiddleware } from '@nestjs/common';
import { Request, Response, NextFunction } from 'express';
import { CheckNodeEnv } from './check-node-env.decorator';

@Injectable()
@NestMiddleware()
export class NodeEnvMiddleware implements NestMiddleware {
  use(req: Request, res: Response, next: NextFunction, @CheckNodeEnv() nodeEnvData: any) {
    if (nodeEnvData.nodeEnv === 'true') {
      next();
    } else {
      res.status(403).send(false);
    }
  }
}
```

