 To create a decorator for Nest.js middleware that checks the `NODE_ENV` variable and behaves accordingly, follow these steps:

First, let's define an interface for the decorator:

```typescript
interface CheckNodeEnvMiddlewareDecorator {
  name: string;
}
```

Next, create the decorator function:

```typescript
import { createDecorator, ExecutionContext } from '@nestjs/common';
import * as process from 'process';

export const CheckNodeEnvMiddleware = createDecorator((): CheckNodeEnvMiddlewareDecorator => ({
  name: 'checkNodeEnv',
}))();

export function checkNodeEnvMiddleware(condition: boolean): MethodDecorator {
  return (target: Object, key: string, desc: PropertyDescriptor) => {
    Reflect.defineMetadata('middleware', [], target, key);
    Reflect.defineMetadata('condition', condition, target, key);
  };
}

CheckNodeEnvMiddleware.prototype.apply = function (constructorFn: Function, _: any, index: number) {
  return (middlewareStack: Function[]) => (req: Request, res: Response, next: Function) => {
    if (process.env.NODE_ENV === 'true' || process.env.NODE_ENV === 'production') {
      next();
      return;
    }

    if (middlewareStack[index].length > 0) {
      const result = middlewareStack[index][0].apply(this, [req, res, next]);
      if (result instanceof Promise) {
        result.then((value) => next());
      } else {
        next();
      }
    } else {
      res.sendStatus(403); // Forbidden status code for unauthorized access
      res.end();
    }
  };
};
```

This decorator is named `@CheckNodeEnvMiddleware`, and it checks the `NODE_ENV` environment variable in the `apply` method. If it's set to 'true' or 'production', the middleware calls the next middleware in the stack. Otherwise, it returns a 403 error with no content.

